mapper.select:
SELECT

FROM t_app_version

    deleted_flag = 0

        AND app_type = #{query.appType}


        AND version LIKE CONCAT('%', #{query.version}, '%')


        AND current_flag = #{query.currentFlag}


        AND release_time >= #{query.beginDate}


        AND release_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)



    ORDER BY current_flag DESC, COALESCE(release_time, create_time) DESC, version_id DESC

SELECT

FROM t_app_version
WHERE app_type = #{appType}
  AND version = #{version}
LIMIT 1
